"use strict";

function mean(values) {
  if (!Array.isArray(values)) throw new TypeError("values must be an array");
  if (values.length === 0) throw new RangeError("values must not be empty");
  return values.reduce((a, b) => a + b, 0) / values.length;
}

function variance(values) {
  if (!Array.isArray(values)) throw new TypeError("values must be an array");
  if (values.length < 2) throw new RangeError("variance needs at least two values");
  const m = mean(values);
  return values.reduce((a, b) => a + (b - m) ** 2, 0) / (values.length - 1);
}

module.exports = { mean, variance };

